     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Account/account_id> ?account_id ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Account/date> ?date .
  ?l a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan> ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/hasAccount> ?a ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/duration> ?dur ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/amount> ?amount .
  FILTER(STRSTARTS(STR(?date), "1993"))
  FILTER(xsd:integer(?dur) > 12)
  {
    SELECT (MAX(?amount2) AS ?maxAmt) WHERE {
      ?a2 a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Account> ;
          <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Account/date> ?date2 .
      ?l2 a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan> ;
          <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/hasAccount> ?a2 ;
          <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/duration> ?dur2 ;
          <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/amount> ?amount2 .
      FILTER(STRSTARTS(STR(?date2), "1993"))
      FILTER(xsd:integer(?dur2) > 12)
    }
  }
  FILTER(xsd:integer(?amount) = ?maxAmt)
}

