        <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/District/district_id> ?distId ;
        <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/District/a11> ?sal2 .
