SELECT (SUM(IF(?status = "C", 1, 0)) / COUNT(*) * 100 AS ?percentage)
WHERE {
  ?loan a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan> ;
        <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/amount> ?amount ;
        <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/status> ?status .
  FILTER(xsd:decimal(?amount) < 100000)
