SELECT ?account_id ?gap
WHERE {
  {
    SELECT (MIN(?a11) AS ?minA11) (MAX(?a11) AS ?maxA11)
    WHERE {
      ?d a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/District> ;
         <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/District/a11> ?a11 .
    }
  }
  {
    SELECT (MIN(?bd) AS ?minBd)
    WHERE {
      ?c a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Client> ;
         <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Client/gender> "F" ;
         <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Client/birth_date> ?bd .
    }
  }
  ?client a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Client> ;
          <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Client/gender> "F" ;
          <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Client/birth_date> ?minBd ;
          <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Client/hasDistrict> ?district .
  ?district <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/District/a11> ?districtA11 .
  FILTER(xsd:decimal(?districtA11) = ?minA11)
  ?disp a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Disp> ;
        <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Disp/hasClient> ?client ;
        <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Disp/hasAccount> ?account .
  ?account <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Account/account_id> ?account_id .
  BIND(?maxA11 - ?minA11 AS ?gap)
}

