  ?account a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Account> ;
    <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Account/district_id> "1"^^xsd:long .
  ?loan a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan> ;
    <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/account_id> ?accId ;
    <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/status> ?status .
  ?account <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Account/account_id> ?accId .
  FILTER(?status IN ("C", "D"))
}

SELECT (COUNT(?loan) AS ?n) WHERE {
  ?loan a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan> ;
        <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/date> ?date ;
        <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/amount> ?amount ;
        <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/hasAccount> ?account .
  ?account <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Account/frequency> ?frequency .
  FILTER(?date >= "1995-01-01" && ?date <= "1997-12-31")
  FILTER(xsd:decimal(?amount) >= 250000)
  FILTER(?frequency = "POPLATEK MESICNE")
}

