     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Trans/type> "VYDAJ" ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Trans/date> ?d ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Trans/amount> ?amount ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Trans/hasAccount> ?acc .
  OPTIONAL { ?t <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Trans/operation> ?op }
  FILTER(!BOUND(?op) || ?op != "VYBER KARTOU")
  FILTER(STRSTARTS(STR(?d), "1996-01"))
  ?acc <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Account/hasDistrict> ?dist .
  ?dist <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/District/a2> ?districtName .
}
ORDER BY DESC(xsd:decimal(?amount))
LIMIT 10

