           <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Account/district_id> "1"^^<http://www.w3.org/2001/XMLSchema#long> .
  ?loan a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan> ;
