        <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/status> ?status .
  FILTER(?status IN ("C", "D"))
}

SELECT (COUNT(?c) AS ?n) WHERE {
  {
    SELECT ?d WHERE {
      ?dist a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/District> ;
            <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/District/district_id> ?d ;
            <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/District/a15> ?a15 .
    }
    ORDER BY DESC(?a15)
    LIMIT 1
    OFFSET 1
  }
  ?c a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Client> ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Client/district_id> ?d ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Client/gender> ?g .
  FILTER(?g = "M")
}

SELECT DISTINCT ?client_id WHERE {
  ?t a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Trans> ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Trans/operation> "VYBER KARTOU" ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Trans/date> ?date ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Trans/amount> ?amount ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Trans/account_id> ?accId .
  FILTER(STRSTARTS(STR(?date), "1998"))
  {
    SELECT (AVG(?amt2) AS ?avgAmt) WHERE {
      ?t2 a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Trans> ;
          <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Trans/operation> "VYBER KARTOU" ;
          <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Trans/date> ?date2 ;
          <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Trans/amount> ?amt2 .
      FILTER(STRSTARTS(STR(?date2), "1998"))
    }
  }
  FILTER(xsd:decimal(?amount) < ?avgAmt)
  ?d a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Disp> ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Disp/account_id> ?accId ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Disp/type> "OWNER" ;
     <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Disp/client_id> ?client_id .
}

SELECT (AVG(?a15) AS ?avgCrimes)
WHERE {
  {
    SELECT DISTINCT ?dist ?a15 WHERE {
      ?dist a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/District> ;
            <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/District/a15> ?a15 .
      FILTER(xsd:decimal(?a15) > 4000)
      ?acc a <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Account> ;
           <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Account/hasDistrict> ?dist ;
           <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Account/date> ?date .
      FILTER(SUBSTR(STR(?date), 1, 4) >= "1997")
    }
  }
}

