        <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/status> "D" ;
        <http://bird-bird_financial-ontology-20260809-234042/ontology/vkg-bird_financial/Loan/hasAccount> ?acc .
